#!/usr/bin/env python3
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"


def write_file(path: Path, content: str) -> None:
    path.write_text(content, encoding="utf-8")


def render_png(dot_path: Path, png_path: Path) -> None:
    cmd = ["dot", "-Tpng", "-Gdpi=185", str(dot_path), "-o", str(png_path)]
    subprocess.run(cmd, check=True)


def architecture_dot() -> str:
    return r'''digraph AuraVaultArchitecture {
  graph [
    rankdir=TB,
    bgcolor="#0b1020",
    pad=0.55,
    nodesep=1.05,
    ranksep="1.15 equally",
    splines=ortho,
    overlap=false,
    outputorder=edgesfirst,
    fontname="Helvetica"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fontname="Helvetica",
    fontsize=14,
    fontcolor="#f3f8ff",
    color="#d7e4ff",
    penwidth=1.6,
    margin="0.30,0.22"
  ];

  edge [
    color="#d7e4ff",
    penwidth=1.8,
    arrowsize=0.9,
    fontname="Helvetica",
    fontsize=11,
    fontcolor="#f3f8ff"
  ];

  subgraph cluster_iot {
    label="CAPA IOT";
    labelloc=t;
    fontsize=17;
    fontcolor="#cde5ff";
    color="#3b5e9a";
    fillcolor="#12213d";
    style="rounded,filled";

    simulator [label="Simulador IoT", fillcolor="#296d98"];
    mosquitto [label="Mosquitto", fillcolor="#2f7f86"];
    iotagent [label="IoT Agent", fillcolor="#437b99"];

    { rank=same; simulator; mosquitto; iotagent; }
  }

  subgraph cluster_context {
    label="CAPA CONTEXTO";
    labelloc=t;
    fontsize=17;
    fontcolor="#cde5ff";
    color="#496da8";
    fillcolor="#142845";
    style="rounded,filled";

    orion [label="Orion CB", fillcolor="#4f6aa5"];
  }

  subgraph cluster_persist {
    label="CAPA PERSISTENCIA";
    labelloc=t;
    fontsize=17;
    fontcolor="#d8f1ff";
    color="#2f7b80";
    fillcolor="#132f38";
    style="rounded,filled";

    ql [label="QuantumLeap", fillcolor="#2f7f86"];
    crate [label="CrateDB", fillcolor="#2f6e7b"];

    { rank=same; ql; crate; }
  }

  subgraph cluster_app {
    label="CAPA APLICACION";
    labelloc=t;
    fontsize=17;
    fontcolor="#e4f2ff";
    color="#7a689f";
    fillcolor="#2a2240";
    style="rounded,filled";

    flask [label="Flask backend", fillcolor="#5d4a86"];
    sk [label="scikit-learn", fillcolor="#5b6b92"];

    { rank=same; flask; sk; }
  }

  subgraph cluster_front {
    label="CAPA PRESENTACION";
    labelloc=t;
    fontsize=17;
    fontcolor="#fff1d6";
    color="#9a7b3a";
    fillcolor="#3a2e13";
    style="rounded,filled";

    frontend [label="Frontend", fillcolor="#8a6b2f"];
    leaflet [label="Leaflet", fillcolor="#7f6a35"];
    chartjs [label="Chart.js", fillcolor="#7f6a35"];
    threejs [label="Three.js", fillcolor="#7f6a35"];
    grafana [label="Grafana", fillcolor="#7f6a35"];
    chatbot [label="Chatbot LLM", fillcolor="#7f6a35"];

    { rank=same; frontend; leaflet; chartjs; threejs; grafana; chatbot; }
  }

  simulator -> mosquitto [label="MQTT publish"];
  mosquitto -> iotagent [label="telemetria"];
  iotagent -> orion [label="upsert NGSI-LD"];

  orion -> ql [label="suscripciones"];
  ql -> crate [label="timeseries"];
  ql -> flask [label="historicos"];
  crate -> flask [label="consulta analitica"];

  flask -> frontend [label="REST + WebSocket"];
  frontend -> leaflet [label="mapa"];
  frontend -> chartjs [label="graficas"];
  frontend -> threejs [label="gemelo 3D"];
  frontend -> grafana [label="dashboards"];
  frontend -> chatbot [label="asistente"];

  ql -> sk [label="flujo lateral ML", color="#ffd07a", fontcolor="#ffe4aa", penwidth=2.0];
  sk -> flask [label="riesgo", color="#ffd07a", fontcolor="#ffe4aa", penwidth=2.0];

  iotagent -> ql [style=invis, weight=10];
