    ranksep="1.30 equally",
    splines=spline,
    overlap=false,
    outputorder=edgesfirst,
    fontname="Helvetica"
  ];

  node [
    shape=box,
    style="rounded,filled",
    fontname="Helvetica",
    fontsize=12,
    fontcolor="#f3f8ff",
    color="#d7e4ff",
    penwidth=1.5,
    margin="0.35,0.24"
  ];

  edge [
    color="#d7e4ff",
    penwidth=1.6,
    arrowsize=0.85,
    fontname="Helvetica",
    fontsize=10,
    fontcolor="#f3f8ff"
  ];

  museum [
    fillcolor="#4b6ea8",
    label="Museum\nname, location, museumType, facilities"
  ];

  room [
    fillcolor="#3f7a66",
    label="Room\nname, floor, area, capacity, status"
  ];

  indoor [
    fillcolor="#2f7f86",
    label="IndoorEnvironmentObserved\ndateObserved, temperature, relativeHumidity, co2, illuminance"
  ];

  noise [
    fillcolor="#2f7f86",
    label="NoiseLevelObserved\ndateObserved, LAeq, LAmax, LAS, sonometerClass"
  ];

  crowd [
    fillcolor="#2f7f86",
    label="CrowdFlowObserved\ndateObserved, peopleCount, occupancy, averageCrowdSpeed, congested"
  ];

  alert [
    fillcolor="#8a4e4e",
    label="Alert\ncategory, subCategory, severity, status, dateIssued"
  ];

  device [
    fillcolor="#4b5f9d",
    label="Device\ncontrolledProperty, deviceState, batteryLevel, value, refDeviceModel"
  ];

  devicemodel [
    fillcolor="#436f9c",
    label="DeviceModel\nmodelName, manufacturerName, category, supportedProtocol, supportedUnits"
  ];

  artwork [
    fillcolor="#7e5b9d",
    label="Artwork\nname, artist, material, degradationRisk, conditionStatus"
  ];

  actuator [
    fillcolor="#8a6b3f",
    label="Actuator\nactuatorType, status, commandSent, targetProperty, isControlledBy"
  ];

  { rank=same; museum; devicemodel; }
  { rank=same; room; device; }
  { rank=same; indoor; noise; crowd; alert; }
  { rank=same; artwork; actuator; }

  museum -> room [label="contains / isParentOf"];
  room -> museum [label="isLocatedIn"];

  room -> indoor [label="refPointOfInterest"];
  room -> noise [label="refPointOfInterest"];
  room -> crowd [label="refPointOfInterest"];

  indoor -> device [label="refDevice"];
  noise -> device [label="refDevice"];
  crowd -> device [label="refDevice"];

  device -> devicemodel [label="refDeviceModel"];

  room -> artwork [label="isExposedIn"];
  artwork -> room [label="isExposedIn"];

  actuator -> room [label="isLocatedIn"];
  actuator -> device [label="isControlledBy"];

  alert -> device [label="alertSource"];
  alert -> room [label="alertSource"];
  alert -> artwork [label="alertSource"];

  museum -> device [style=invis, weight=4];
  device -> artwork [style=invis, weight=3];
  indoor -> artwork [style=invis, weight=2];
}
'''


def main() -> None:
    DOCS.mkdir(parents=True, exist_ok=True)

    architecture_dot_path = DOCS / "architecture_graph.dot"
    data_model_dot_path = DOCS / "data_model_graph.dot"
    architecture_png = DOCS / "architecture.png"
    data_model_png = DOCS / "data_model.png"

